<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="__SITE_DESCRIPTION__">
<meta name="keywords" content="__SITE_KEYWORDS__">
<title>__SITE_NAME__</title>
__SITE_FAVICON_TAG__
<script src="https://unpkg.com/vue@3/dist/vue.global.prod.js"></script>
<style>
:root{--bg:#f5f7fb;--surface:#fff;--ink:#172033;--muted:#7a879b;--line:#e7ebf2;--primary:#5d5ce9;--primary-2:#8d7cff;--success:#1fa971;--warning:#d88b2d;--danger:#dd4f68;--shadow:0 16px 42px rgba(33,48,89,.08)}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 10% 0,#eceaff 0,transparent 30%),linear-gradient(180deg,#f7f9ff 0,#f8fafc 60%,#f4f7fb 100%);color:var(--ink);font:14px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft Yahei",sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}.app{min-height:100vh}.topbar{height:72px;position:sticky;top:0;z-index:20;background:#ffffffdc;backdrop-filter:blur(18px);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 28px}.brand{display:flex;align-items:center;gap:12px;font-weight:850;letter-spacing:.01em}.logo{width:38px;height:38px;border-radius:13px;display:grid;place-items:center;color:#fff;background:linear-gradient(135deg,var(--primary),var(--primary-2));box-shadow:0 10px 20px #645dea38;font-size:18px}.logo.logo-image{padding:0;overflow:hidden;background:#fff;color:transparent}.logo.logo-image img{width:100%;height:100%;object-fit:cover;display:block}.top-right{display:flex;align-items:center;gap:12px}.avatar{width:38px;height:38px;border-radius:50%;object-fit:cover;background:#e6eafe}.layout{display:grid;grid-template-columns:252px minmax(0,1fr);max-width:1500px;margin:auto}.sidebar{padding:24px 16px;min-height:calc(100vh - 72px)}.nav-title{color:#a0aabd;font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;margin:16px 12px 8px}.nav{display:flex;flex-direction:column;gap:4px}.nav-item{border:0;background:transparent;color:#64718a;border-radius:13px;padding:12px 13px;display:flex;align-items:center;gap:11px;text-align:left;font-weight:750}.nav-item:hover,.nav-item.active{background:#ededff;color:var(--primary)}.nav-item .icon{width:20px;text-align:center}.content{padding:30px 32px 70px;min-width:0}.site-footer{max-width:1500px;margin:0 auto 26px;padding:0 32px;color:var(--muted);font-size:13px;line-height:1.7}.hero{border-radius:26px;padding:30px 32px;background:linear-gradient(135deg,#1d2450,#5d5ce9 60%,#907eff);color:#fff;display:flex;justify-content:space-between;gap:24px;box-shadow:0 20px 50px #5d5ce932;margin-bottom:22px}.hero h1{margin:6px 0 8px;font-size:29px}.hero p{margin:0;color:#e8eaff}.hero-stat{min-width:180px;padding:17px 19px;background:#ffffff18;border:1px solid #ffffff2e;border-radius:17px}.hero-stat small{color:#dfe2ff}.hero-stat b{display:block;font-size:26px;margin-top:5px}.page-head{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:17px}.page-head h2{margin:0;font-size:24px}.page-head p{margin:5px 0 0;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.stat,.panel,.auth-card{background:var(--surface);border:1px solid var(--line);border-radius:19px;box-shadow:var(--shadow)}.stat{padding:18px}.stat small{color:var(--muted);font-weight:700}.stat strong{display:block;font-size:27px;margin-top:8px}.panel{padding:20px;margin-bottom:18px}.panel h3{margin:0 0 15px;font-size:17px}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:13px}.table th{background:#fafbfe;color:#8290a5;font-weight:800;text-align:left}.table th,.table td{padding:12px 10px;border-bottom:1px solid var(--line);white-space:nowrap}.table tr:last-child td{border-bottom:0}.badge{display:inline-flex;align-items:center;border-radius:999px;padding:4px 9px;background:#eef1f7;color:#5d6b81;font-size:12px;font-weight:800}.badge.success{background:#e9f9f0;color:#148451}.badge.warning{background:#fff4e2;color:#a7690e}.badge.danger{background:#ffedf1;color:#c73752}.badge.info{background:#ececff;color:#5a56d7}.btn{border:0;border-radius:11px;padding:10px 14px;background:#eef1f7;color:#364359;font-weight:800}.btn:hover{filter:brightness(.98)}.btn.primary{color:#fff;background:var(--primary);box-shadow:0 8px 18px #5d5ce92f}.btn.success{color:#137b4c;background:#e8f8ef}.btn.warning{color:#99600a;background:#fff2dc}.btn.danger{color:#bd2f4b;background:#ffedf1}.btn.ghost{background:transparent;border:1px solid var(--line)}.btn.sm{padding:7px 10px;font-size:12px}.btn:disabled{cursor:not-allowed;opacity:.55}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.field{display:flex;flex-direction:column;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:13px;font-weight:800;color:#536178}.field input,.field select,.field textarea{width:100%;border:1px solid #dfe5ef;border-radius:11px;padding:11px 12px;outline:0;background:#fff;color:var(--ink)}.field textarea{min-height:96px;resize:vertical}.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--primary);box-shadow:0 0 0 3px #5d5ce91d}.hint{font-size:12px;color:var(--muted)}.switch{display:flex;align-items:center;gap:8px}.switch input{width:18px;height:18px}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.tab{border:0;background:#edf0f7;color:#68758b;border-radius:10px;padding:9px 13px;font-weight:800}.tab.active{background:#eaeaff;color:var(--primary)}.product-card{padding:18px;display:flex;flex-direction:column;gap:13px;min-height:190px}.product-card h3{margin:0;font-size:16px}.product-meta{display:flex;flex-wrap:wrap;gap:7px}.product-price{font-size:22px;font-weight:850;color:var(--primary)}.product-actions{display:flex;gap:8px;margin-top:auto}.order-form{display:grid;grid-template-columns:1fr 1fr;gap:16px}.order-form .wide{grid-column:1/-1}.qq-box{display:flex;align-items:center;gap:10px}.qq-box input{flex:1}.qq-preview{width:45px;height:45px;border-radius:13px;object-fit:cover;background:#eef1ff;border:1px solid var(--line)}.feed-toolbar{display:flex;gap:10px;align-items:end}.feed-toolbar .field{flex:1}.feed-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:14px}.feed-item{border:1px solid var(--line);border-radius:14px;padding:13px;background:#fbfcff;cursor:pointer}.feed-item:hover{border-color:#aca8ff;box-shadow:0 6px 16px #5d5ce914}.feed-item.selected{border-color:var(--primary);background:#f2f1ff}.feed-images{display:flex;gap:7px;overflow:auto;margin-top:10px}.feed-images img{width:88px;height:66px;border-radius:8px;object-fit:cover}.notice{position:fixed;right:22px;bottom:22px;z-index:50;background:#1c2741;color:#fff;border-radius:12px;padding:13px 16px;box-shadow:0 16px 32px #17223d33;max-width:380px}.modal-backdrop{position:fixed;inset:0;background:#17223d72;z-index:40;display:grid;place-items:center;padding:20px}.modal{width:min(720px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:22px;padding:24px;box-shadow:0 24px 70px #11182744}.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.modal-head h3{margin:0}.close{border:0;background:#eef1f7;width:32px;height:32px;border-radius:50%}.login-page{min-height:100vh;display:grid;place-items:center;padding:24px}.auth-shell{width:min(1050px,100%);display:grid;grid-template-columns:1.1fr .9fr;overflow:hidden;border-radius:28px;background:#fff;box-shadow:0 24px 70px #26387318;border:1px solid var(--line)}.auth-intro{padding:50px;background:linear-gradient(145deg,#1c2452,#655deb 63%,#947fff);color:#fff}.auth-intro h1{font-size:36px;line-height:1.15;margin:24px 0 14px}.auth-intro p{color:#e5e8ff;max-width:430px}.auth-points{display:grid;gap:12px;margin-top:35px}.auth-point{display:flex;gap:11px;align-items:center}.auth-point i{width:29px;height:29px;border-radius:10px;background:#ffffff22;display:grid;place-items:center;font-style:normal}.auth-card{box-shadow:none;border:0;border-radius:0;padding:42px}.auth-card h2{margin:0 0 8px;font-size:25px}.auth-card>p{margin:0 0 24px;color:var(--muted)}.auth-switch{display:flex;background:#f1f3f8;border-radius:12px;padding:4px;margin-bottom:20px}.auth-switch button{flex:1;border:0;background:transparent;padding:10px;border-radius:9px;color:var(--muted);font-weight:800}.auth-switch button.active{background:#fff;color:var(--primary);box-shadow:0 4px 10px #27345a10}.auth-actions{display:flex;justify-content:flex-end;margin-top:21px}.captcha{height:43px;border-radius:10px;border:1px solid var(--line);cursor:pointer}.json-box{background:#111827;color:#d8e4ff;border-radius:12px;padding:13px;white-space:pre-wrap;word-break:break-all;font:12px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace}.empty{padding:34px;text-align:center;color:#9aa6b9}.mobile-menu{display:none;border:0;background:#eef1f8;border-radius:10px;padding:8px 10px}.admin-layout{display:grid;grid-template-columns:180px 1fr;gap:18px}.admin-side{padding:12px;background:#fbfcff;border:1px solid var(--line);border-radius:16px;height:max-content}.admin-side button{width:100%;border:0;background:transparent;text-align:left;border-radius:10px;padding:10px;color:#69768a;font-weight:750}.admin-side button.active{background:#ececff;color:var(--primary)}.kicker{font-size:12px;color:var(--muted);font-weight:800;letter-spacing:.1em;text-transform:uppercase}.danger-note{border:1px solid #ffc4cf;background:#fff4f6;color:#a92742;border-radius:14px;padding:13px;font-weight:800}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:16px}
@media(max-width:1100px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.layout{grid-template-columns:210px 1fr}}
@media(max-width:820px){.topbar{padding:0 16px}.mobile-menu{display:block}.layout{display:block}.sidebar{position:fixed;left:-280px;top:72px;bottom:0;width:260px;background:#fff;z-index:18;transition:.2s;box-shadow:10px 0 30px #15213b18}.sidebar.open{left:0}.content{padding:20px 16px 60px}.hero{padding:23px;flex-direction:column}.hero-stat{min-width:0}.auth-shell{grid-template-columns:1fr}.auth-intro{display:none}.auth-card{padding:28px}.order-form,.two-col{grid-template-columns:1fr}.feed-list{grid-template-columns:1fr}.admin-layout{grid-template-columns:1fr}.admin-side{display:flex;gap:6px;overflow:auto}.admin-side button{white-space:nowrap;width:auto}.page-head{align-items:flex-start;flex-direction:column}}
@media(max-width:540px){.grid,.cards{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.topbar .user-name{display:none}.content{padding-left:12px;padding-right:12px}.panel{padding:16px}}
</style>
</head>
<body>
<div id="app">
  <div v-if="!isLogged" class="login-page">
    <div class="auth-shell">
      <section class="auth-intro">
        <div class="brand">__SITE_BRAND__</div>
        <h1>把上游能力，变成你的增长引擎。</h1>
        <p>统一商品、用户组、额度、订单、充值与 API 对接，让每一笔订单都有迹可循。</p>
        <div class="auth-points"><div class="auth-point"><i>✓</i><span>按用户组自动计算加价与折扣</span></div><div class="auth-point"><i>✓</i><span>腾讯云 / 阿里云 / 自定义短信扩展</span></div><div class="auth-point"><i>✓</i><span>上游补单、退款、说说预览全链路支持</span></div></div>
      </section>
      <section class="auth-card">
        <div class="auth-switch"><button :class="{active:authMode==='login'}" @click="authMode='login'">登录</button><button :class="{active:authMode==='register'}" @click="authMode='register'">注册</button></div>
        <template v-if="authMode==='login'">
          <h2>欢迎回来</h2><p>使用账号登录你的控制台。</p>
          <div class="tabs"><button class="tab" :class="{active:loginMode==='user'}" @click="loginMode='user'">用户登录</button><button class="tab" :class="{active:loginMode==='admin'}" @click="loginMode='admin'">管理员登录</button></div>
          <form @submit.prevent="doLogin"><div class="field"><label>用户名</label><input v-model.trim="login.username" autocomplete="username" required></div><div class="field" style="margin-top:14px"><label>密码</label><input v-model="login.password" type="password" autocomplete="current-password" required></div><div class="field" style="margin-top:14px" v-if="loginMode==='admin' || settings.login_need_image_captcha==='1'"><label>图片验证码</label><div style="display:flex;gap:10px"><input v-model.trim="login.captcha" required><img class="captcha" src="/captcha/image" @click="refreshCaptcha"></div></div><div class="auth-actions"><button class="btn primary" :disabled="loading">登录</button></div></form>
        </template>
        <template v-else>
          <h2>创建你的账号</h2><p>注册必须填写用户名、昵称、QQ号与密码。</p>
          <form @submit.prevent="doRegister"><div class="form-grid"><div class="field"><label>用户名</label><input v-model.trim="register.username" pattern="[A-Za-z0-9]{4,32}" required></div><div class="field"><label>昵称</label><input v-model.trim="register.nickname" required></div><div class="field"><label>QQ号</label><input v-model.trim="register.qq" inputmode="numeric" required></div><div class="field"><label>密码</label><input v-model="register.password" type="password" minlength="6" required></div><div class="field" v-if="settings.register_need_email==='1'"><label>邮箱</label><input v-model.trim="register.email" type="email" required></div><div class="field" v-if="settings.register_need_mobile==='1'"><label>手机号</label><input v-model.trim="register.mobile" required></div><div class="field"><label>邀请码 <span class="hint">可选</span></label><input v-model.trim="register.invite_code"></div><div class="field" v-if="settings.register_need_image_captcha!=='0'"><label>图片验证码</label><div style="display:flex;gap:10px"><input v-model.trim="register.captcha" required><img class="captcha" src="/captcha/image" @click="refreshCaptcha"></div></div></div><div class="auth-actions"><button class="btn primary" :disabled="loading">注册并登录</button></div></form>
        </template>
      </section>
    </div>
  </div>

  <div v-else class="app">
    <header class="topbar"><div style="display:flex;align-items:center;gap:12px"><button class="mobile-menu" @click="mobileNav=!mobileNav">☰</button><div class="brand">__SITE_BRAND__</div></div><div class="top-right"><span class="user-name">{{user.nickname}} · {{user.group_name||'普通用户'}}</span><img class="avatar" :src="user.avatar||qqAvatar"><button class="btn ghost sm" @click="logout">退出</button></div></header>
    <div class="layout">
      <aside class="sidebar" :class="{open:mobileNav}">
        <div class="nav-title">Workspace</div><div class="nav"><button class="nav-item" :class="{active:tab==='home'}" @click="selectTab('home')"><span class="icon">⌂</span>首页</button><button class="nav-item" :class="{active:tab==='place'}" @click="selectTab('place')"><span class="icon">✦</span>速刷下单</button><button class="nav-item" :class="{active:tab==='dock'}" @click="selectTab('dock')"><span class="icon">↗</span>对接下单</button><button class="nav-item" :class="{active:tab==='orders'}" @click="selectTab('orders')"><span class="icon">▤</span>查单系统</button><button class="nav-item" :class="{active:tab==='recharge'}" @click="selectTab('recharge')"><span class="icon">＋</span>额度充值</button><button class="nav-item" :class="{active:tab==='groups'}" @click="selectTab('groups')"><span class="icon">◈</span>代理等级</button><button class="nav-item" :class="{active:tab==='invites'}" @click="selectTab('invites')"><span class="icon">◎</span>邀请管理</button></div>
        <template v-if="isAdmin"><div class="nav-title">Admin</div><div class="nav"><button class="nav-item" :class="{active:tab==='admin'}" @click="openAdmin('dashboard')"><span class="icon">▦</span>管理后台</button></div></template>
      </aside>
      <main class="content">
        <section v-if="tab==='home'">
          <div class="hero"><div><div class="kicker">Personal console</div><h1>你好，{{user.nickname}}</h1><p>今天也把每一笔订单，做得清晰、稳定、可追踪。</p></div><div class="hero-stat"><small>当前余额</small><b>{{money(user.balance)}} {{currency}}</b></div></div>
          <div class="grid"><div class="stat"><small>用户组</small><strong>{{user.group_name||'普通用户'}}</strong></div><div class="stat"><small>累计消费</small><strong>{{money(user.total_consume)}} <small>{{currency}}</small></strong></div><div class="stat"><small>累计充值</small><strong>{{money(user.total_recharge)}} <small>{{currency}}</small></strong></div><div class="stat"><small>代理状态</small><strong>{{isAgent?'可对接':'普通用户'}}</strong></div></div>
          <div class="two-col" style="margin-top:18px"><div class="panel"><h3>快捷入口</h3><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn primary" @click="selectTab('place')">开始下单</button><button class="btn" @click="selectTab('orders')">查看订单</button><button class="btn" @click="selectTab('recharge')">充值额度</button></div></div><div class="panel"><h3>对接状态</h3><div class="hint">只有 Agent 策略用户可以生成 API Key。当前状态：<span class="badge" :class="isAgent?'success':'warning'">{{isAgent?'已具备代理策略':'未开启代理策略'}}</span></div><div class="hint" v-if="isAgent" style="margin-top:10px">API Key：<code>{{user.api_key||'未生成'}}</code></div></div></div>
        </section>

        <section v-if="tab==='place'||tab==='dock'">
          <div class="page-head"><div><h2>{{tab==='place'?'速刷下单':'对接下单'}}</h2><p>{{tab==='place'?'选择商品，填写目标信息后即可提交。':'使用代理策略下单，价格与普通下单一致，并保留完整订单记录。'}}</p></div><button class="btn ghost" @click="loadProducts">刷新商品</button></div>
          <div v-if="!selectedProduct" class="cards"><article v-for="p in products" :key="p.id" class="product-card panel"><div style="display:flex;justify-content:space-between;gap:10px"><h3>{{p.name}}</h3><span class="badge info">{{p.upstream_level||'标准'}}</span></div><div class="product-meta"><span class="badge">{{p.min_num}} - {{p.max_num}}</span><span class="badge">步长 {{p.step_num}}</span><span class="badge" v-if="p.min_delayed">延迟 ≥ {{p.min_delayed}}</span></div><div class="hint">{{descText(p.desc)||'支持稳定上游供货与订单状态同步。'}}</div><div class="product-price">{{money(p.preview_price)}} {{currency}} 起</div><div class="product-actions"><button class="btn primary" @click="chooseProduct(p,tab)">立即下单</button><button class="btn ghost" @click="selectedProduct=p">详情</button></div></article><div v-if="!products.length" class="panel empty">暂无可下单商品，请联系管理员同步商品。</div></div>
          <div v-else class="panel"><div class="page-head"><div><h3 style="margin:0">{{selectedProduct.name}}</h3><p>起售价：{{money(selectedProduct.preview_price)}} {{currency}} · 数量范围 {{selectedProduct.min_num}} - {{selectedProduct.max_num}}</p><div v-if="quotedPrice" class="badge success" style="margin-top:8px">本次预计实付：{{money(quotedPrice.price)}} {{currency}}<span v-if="Number(quotedPrice.discount_rate)<1"> · 折扣 {{quotedPrice.discount_rate}}</span></div></div><button class="btn ghost" @click="selectedProduct=null">返回商品列表</button></div>
            <div class="danger-note" v-if="tab==='dock'&&!isAgent">当前账号未开启 Agent 策略，不能对接下单。</div>
            <div class="order-form" style="margin-top:16px"><div v-for="f in selectedInputs" :key="f.name" class="field"><label>{{f.title||f.name}} <span v-if="f.required!==false" style="color:var(--danger)">*</span></label><template v-if="fieldType(f)==='qq'"><div class="qq-box"><input :value="fieldValue(f)" @input="setField(f,$event.target.value)" :placeholder="f.placeholder||'请输入QQ号'"><img class="qq-preview" :src="qqAvatar" alt="QQ头像"></div><span class="hint">头像会随 QQ 号变化，方便核对是否输错。</span></template><template v-else-if="['setnum','num','number'].includes(fieldType(f))"><input type="number" :min="selectedProduct.min_num" :max="selectedProduct.max_num" :step="selectedProduct.step_num" :value="fieldValue(f)" @input="setField(f,$event.target.value)" :placeholder="f.placeholder||'请输入数量'"></template><template v-else-if="fieldType(f)==='feed'"><div style="display:flex;gap:8px"><input style="flex:1" :value="fieldValue(f)" @input="setField(f,$event.target.value)" :placeholder="f.placeholder||'请输入说说ID'"><button class="btn" type="button" @click="feedQq=form.qq;refreshFeed()">获取说说</button></div></template><template v-else><input :value="fieldValue(f)" @input="setField(f,$event.target.value)" :placeholder="f.placeholder||''"></template></div><div class="field"><label>限价 <span class="hint">可选</span></label><input v-model="form.limit" type="number" min="1" :placeholder="'默认 '+selectedProduct.price_cost+' '+currency"></div><div class="field"><label>延迟下单</label><label class="switch"><input v-model="form.is_delayed" type="checkbox"> 使用延迟模式</label></div><div class="wide"><button class="btn primary" :disabled="loading|| (tab==='dock'&&!isAgent)" @click="tab==='dock'?submitApiOrder():submitOrder()">提交订单</button></div></div>
            <div v-if="selectedFeedInput&&feed.length" class="panel" style="margin:18px 0 0;padding:16px;background:#fbfcff"><h3>选择说说</h3><div class="feed-list"><div v-for="item in feed" :key="item.feed_id||item.id" class="feed-item" :class="{selected:String(form.feed_id)===String(item.feed_id||item.id)}" @click="selectFeed(item)"><div style="font-weight:800">{{item.nickname||'未命名用户'}} · {{item.feed_id||item.id}}</div><div class="hint" style="margin-top:6px">{{item.content||'可能是转发内容，并非空说说'}}</div><div class="feed-images"><img v-for="(img,i) in (item.images||[])" :key="i" :src="feedImage(img)" alt="说说图片"></div><div class="hint" v-if="item.is_possible_repost" style="margin-top:7px">可能是转发内容，并非空说说</div></div></div></div>
          </div>
        </section>

        <section v-if="tab==='orders'"><div class="page-head"><div><h2>查单系统</h2><p>订单状态、成本、实际花费与售后动作都在这里。</p></div><button class="btn ghost" @click="loadOrders">刷新</button></div><div class="panel"><div class="danger-note">因忘记开权限或者其他原因导致失败的，可申请补单一次，补单后还失败的将不再支持再次补单。</div><div class="table-wrap" style="margin-top:15px"><table class="table"><thead><tr><th>订单号</th><th>商品</th><th>数量</th><th>实付</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{o.upstream_order_no||o.order_no}}</td><td>{{o.product_name||o.upstream_sign}}</td><td>{{o.quantity}}</td><td>{{money(o.user_price)}} {{currency}}</td><td><span class="badge" :class="stateClass(o.state)">{{o.state}}</span></td><td>{{o.created_at}}</td><td><div style="display:flex;gap:6px"><button class="btn sm" @click="showOrder(o)">详情</button><button v-if="o.can_retry" class="btn sm warning" @click="retry(o)">补单</button><button v-if="o.can_refund" class="btn sm danger" @click="refund(o)">退款</button></div></td></tr><tr v-if="!orders.length"><td colspan="7" class="empty">暂无订单</td></tr></tbody></table></div></div></section>

        <section v-if="tab==='recharge'"><div class="page-head"><div><h2>额度充值</h2><p>网站内部只使用“额度”。在线充值会按 10000 额度对应网关 1.00 的规则发起支付。</p></div><button class="btn ghost" @click="loadPayments">刷新</button></div><div class="two-col"><div class="panel"><h3>在线充值</h3><div class="form-grid"><div class="field"><label>充值额度</label><input v-model="rechargeAmount" type="number" min="1" placeholder="例如 100000"></div><div class="field"><label>支付通道</label><select v-model="rechargeChannel"><option value="">请选择</option><option v-for="c in payments.channels||[]" :value="c.id">{{c.name}} · {{c.pay_type}}</option></select></div></div><button class="btn primary" style="margin-top:16px" @click="createRecharge">创建支付订单</button><div v-if="gateway" style="margin-top:16px"><div class="badge success">订单 {{gateway.order_no}} 已创建</div><div class="hint" style="margin-top:9px">请使用支付网关返回的链接完成支付，支付成功后额度会自动到账。</div><div v-if="gateway.gateway&&gateway.gateway.qrcode" style="margin-top:12px"><img :src="gateway.gateway.qrcode" alt="支付二维码" style="width:180px;height:180px;object-fit:contain;border:1px solid #e6eaf2;border-radius:12px;padding:8px;background:#fff"></div><div class="json-box" style="margin-top:10px">{{pretty(gateway.gateway)}}</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><a v-if="gateway.gateway&&gateway.gateway.payurl" class="btn primary" :href="gateway.gateway.payurl" target="_blank">打开支付页面</a><a v-if="gateway.gateway&&gateway.gateway.urlscheme" class="btn" :href="gateway.gateway.urlscheme">唤起支付</a><button class="btn ghost" @click="loadPayments">刷新支付状态</button></div></div></div><div class="panel"><h3>卡密充值</h3><div class="field"><label>卡密</label><input v-model.trim="cardCode" placeholder="输入管理员发放的卡密"></div><button class="btn success" style="margin-top:16px" @click="redeemCard">立即兑换</button><p class="hint" style="margin-top:14px">卡密可为一次性卡密或多次通兑卡密，每次兑换都会记录使用者。</p></div></div><div class="panel"><h3>充值订单</h3><div class="table-wrap"><table class="table"><thead><tr><th>订单号</th><th>充值额度</th><th>赠送额度</th><th>通道</th><th>状态</th><th>时间</th></tr></thead><tbody><tr v-for="r in rechargeOrders" :key="r.id"><td>{{r.order_no}}</td><td>{{money(r.credit_amount)}} {{currency}}</td><td>{{money(r.bonus_amount)}} {{currency}}</td><td>{{r.channel_name||r.pay_type}}</td><td><span class="badge" :class="r.status==='paid'?'success':(r.status==='failed'?'danger':'warning')">{{r.status==='paid'?'已支付':(r.status==='failed'?'失败':'待支付')}}</span></td><td>{{r.created_at}}</td></tr><tr v-if="!rechargeOrders.length"><td colspan="6" class="empty">暂无充值订单</td></tr></tbody></table></div></div></section>

        <section v-if="tab==='groups'"><div class="page-head"><div><h2>代理等级</h2><p>查看所有用户组的门槛、加价与充值赠送规则。</p></div><button class="btn ghost" @click="loadGroups">刷新</button></div><div class="cards"><article v-for="g in groups" :key="g.id" class="panel"><div style="display:flex;justify-content:space-between"><h3>{{g.name}}</h3><span class="badge" :class="g.allow_api_default?'success':'warning'">{{g.allow_api_default?'默认允许对接':'默认不允许对接'}}</span></div><p class="hint">{{g.description||'管理员暂未填写介绍'}}</p><div class="product-meta"><span class="badge">门槛：{{g.threshold_mode}} / {{g.threshold_value}}</span><span class="badge">{{g.markup_mode==='percent'?'百分比加价':'固定加价'}} {{g.markup_value}}</span><span class="badge">充值赠送 {{g.recharge_bonus_rate}}x</span></div></article></div></section>

        <section v-if="tab==='invites'"><div class="page-head"><div><h2>邀请管理</h2><p>默认邀请码为 20 位随机字符串，也可以按规则生成自定义长度邀请码。</p></div><button class="btn ghost" @click="loadInvites">刷新</button></div><div class="two-col"><div class="panel"><h3>创建邀请码</h3><div class="form-grid"><div class="field"><label>长度</label><input v-model="inviteLength" type="number" min="6" max="48" value="20"></div><div class="field"><label>自定义字符串 <span class="hint">可选</span></label><input v-model.trim="inviteCustom" maxlength="48"></div></div><button class="btn primary" style="margin-top:16px" @click="createInvite">创建邀请码</button></div><div class="panel"><h3>邀请规则</h3><p class="hint">新用户使用邀请码注册后，达到管理员配置的有效邀请条件，才会计入有效邀请。</p><div class="badge info">有效条件由后台统一设置</div></div></div><div class="panel"><h3>我的邀请码</h3><div class="table-wrap"><table class="table"><thead><tr><th>邀请码</th><th>长度</th><th>使用次数</th><th>已消耗额度</th><th>状态</th></tr></thead><tbody><tr v-for="i in inviteCodes" :key="i.id"><td><code>{{i.code}}</code></td><td>{{i.length}}</td><td>{{i.used_count}} / {{i.max_uses===-1?'无限':i.max_uses}}</td><td>{{money(i.price_paid)}} {{currency}}</td><td><span class="badge" :class="i.active?'success':'danger'">{{i.active?'可用':'停用'}}</span></td></tr><tr v-if="!inviteCodes.length"><td colspan="5" class="empty">暂无邀请码</td></tr></tbody></table></div></div></section>

        <section v-if="tab==='admin'&&isAdmin"><div class="page-head"><div><h2>管理后台</h2><p>商品、用户、订单、支付与系统设置集中管理。</p></div></div><div class="admin-layout"><div class="admin-side"><button v-for="(label,key) in {dashboard:'首页',products:'商品管理',groups:'用户组',users:'用户管理',orders:'订单管理',cards:'卡密充值',payments:'支付设置',upstream:'上游设置',settings:'系统设置',logs:'系统日志'}" :key="key" :class="{active:adminTab===key}" @click="selectAdmin(key)">{{label}}</button></div><div>
          <div v-if="adminTab==='dashboard'"><div class="grid"><div class="stat"><small>今日订单数</small><strong>{{dashboard.orders_today||0}}</strong></div><div class="stat"><small>总用户数</small><strong>{{dashboard.users_total||0}}</strong></div><div class="stat"><small>今日利润</small><strong>{{money(dashboard.profit_today)}} {{currency}}</strong></div><div class="stat"><small>用户总余额</small><strong>{{money(dashboard.balance_total)}} {{currency}}</strong></div></div><div class="two-col" style="margin-top:18px"><div class="panel"><h3>今日消费排行</h3><div class="table-wrap"><table class="table"><tr v-for="r in (dashboard.today_consume_rank||[])" :key="r.username"><td>{{r.nickname||r.username}}</td><td>{{money(r.total)}} {{currency}}</td></tr><tr v-if="!(dashboard.today_consume_rank||[]).length"><td class="empty">暂无数据</td></tr></table></div></div><div class="panel"><h3>上游货源余额</h3><div style="font-size:28px;font-weight:850;color:var(--primary)">{{dashboard.upstream_balance===null?'未配置':money(dashboard.upstream_balance)+' '+currency}}</div></div></div></div>
          <div v-else-if="adminTab==='products'" class="panel"><div class="page-head"><div><h3>商品管理</h3><p>同步后仍保留管理员配置的前台/对接开关；折扣规则按数量门槛从小到大生效。</p></div><button class="btn primary" @click="syncProducts">更新商品数据</button></div><div class="table-wrap"><table class="table"><thead><tr><th>商品</th><th>成本</th><th>前台</th><th>对接</th><th>启用</th><th>折扣规则</th><th>保存</th></tr></thead><tbody><template v-for="p in products" :key="p.id"><tr><td>{{p.name}}<div class="hint">{{p.upstream_sign}}</div></td><td>{{money(p.price_cost)}} {{currency}}</td><td><input type="checkbox" v-model="p.allow_frontend"></td><td><input type="checkbox" v-model="p.allow_api"></td><td><input type="checkbox" v-model="p.enabled"></td><td><button class="btn sm" @click="p._discountOpen=!p._discountOpen">{{(p.discounts||[]).length}} 条 · {{p._discountOpen?'收起':'编辑'}}</button></td><td><button class="btn sm primary" @click="saveProduct(p)">保存</button></td></tr><tr v-if="p._discountOpen"><td colspan="7"><div style="display:flex;flex-direction:column;gap:10px"><div class="hint">折扣力度范围 0.01-1.0，例如 0.7 表示七折；达到门槛后按该规则计算。</div><div v-for="(d,i) in (p.discounts||[])" :key="i" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><label class="hint">满</label><input v-model.number="d.min_quantity" type="number" min="1" :max="p.max_num" style="width:120px"><label class="hint">件，折扣</label><input v-model.number="d.discount_rate" type="number" min="0.01" max="1" step="0.01" style="width:100px"><button class="btn sm danger" @click="p.discounts.splice(i,1)">删除</button></div><button class="btn sm" style="width:max-content" @click="(p.discounts||(p.discounts=[])).push({min_quantity:p.min_num||1,discount_rate:1})">+ 新增折扣规则</button></div></td></tr></template></tbody></table></div></div>
          <div v-else-if="adminTab==='groups'" class="two-col"><div class="panel"><h3>编辑用户组</h3><div class="form-grid"><div class="field"><label>名称</label><input v-model="adminForm.name"></div><div class="field"><label>编码</label><input v-model="adminForm.group_code"></div><div class="field"><label>门槛模式</label><select v-model="adminForm.threshold_mode"><option value="none">无</option><option value="total_recharge">累计充值</option><option value="total_consume">累计消费</option><option value="invite_count">邀请用户数</option><option value="balance">余额大于</option></select></div><div class="field"><label>门槛数额</label><input v-model="adminForm.threshold_value" type="number"></div><div class="field"><label>加价模式</label><select v-model="adminForm.markup_mode"><option value="fixed">固定加价</option><option value="percent">百分比加价</option></select></div><div class="field"><label>加价数额</label><input v-model="adminForm.markup_value" type="number" step="0.0001"></div><div class="field"><label>充值赠送倍率</label><input v-model="adminForm.recharge_bonus_rate" type="number" min="0.01" step="0.01"></div><div class="field"><label>排序</label><input v-model="adminForm.sort_order" type="number"></div><div class="field full"><label>介绍</label><textarea v-model="adminForm.description"></textarea></div><div class="field"><label class="switch"><input v-model="adminForm.allow_api_default" type="checkbox"> 默认允许对接</label></div><div class="field"><label class="switch"><input v-model="adminForm.downgrade_on_balance" type="checkbox"> 余额不足允许降级</label></div></div><button class="btn primary" style="margin-top:15px" @click="saveGroup">保存用户组</button></div><div class="panel"><div class="page-head"><h3>用户组列表</h3><button class="btn sm" @click="adminForm={name:'',group_code:'group_'+Date.now(),threshold_mode:'none',threshold_value:0,markup_mode:'fixed',markup_value:0,recharge_bonus_rate:1,sort_order:0,allow_api_default:0,downgrade_on_balance:0}">新增</button></div><table class="table"><tr v-for="g in groups" :key="g.id"><td>{{g.name}}</td><td><span class="badge">{{g.threshold_mode}} {{g.threshold_value}}</span></td><td><button class="btn sm" @click="editGroup(g)">编辑</button></td></tr></table></div></div>
          <div v-else-if="adminTab==='users'" class="panel"><div class="page-head"><h3>用户管理</h3><button class="btn" @click="adminForm={username:'',nickname:'',qq:'',password:'',user_group_id:groups[0]?.id||0,account_role:'member',strategy_user:1,strategy_agent:0,status:'active',balance:0}">新增用户</button></div><div class="table-wrap"><table class="table"><thead><tr><th>用户</th><th>UID</th><th>用户组</th><th>角色</th><th>余额</th><th>策略</th><th>操作</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td>{{u.nickname}}<div class="hint">{{u.username}}</div></td><td>{{u.uid}}</td><td>{{u.group_name}}</td><td>{{u.account_role}}</td><td>{{money(u.balance)}} {{currency}}</td><td>{{u.strategy_agent?'Agent':'User'}}</td><td><div style="display:flex;gap:6px"><button class="btn sm" @click="editUser(u)">编辑</button><button class="btn sm" @click="resetKey(u)">重置Key</button><button class="btn sm danger" @click="deleteUser(u)">删除</button></div></td></tr></tbody></table></div><div class="panel" style="margin-top:16px;background:#fbfcff"><h3>用户编辑</h3><div class="form-grid"><div class="field"><label>用户名</label><input v-model="adminForm.username"></div><div class="field"><label>昵称</label><input v-model="adminForm.nickname"></div><div class="field"><label>QQ</label><input v-model="adminForm.qq"></div><div class="field"><label>密码</label><input v-model="adminForm.password" type="password" placeholder="留空不修改"></div><div class="field"><label>用户组</label><select v-model="adminForm.user_group_id"><option v-for="g in groups" :value="g.id">{{g.name}}</option></select></div><div class="field"><label>余额</label><input v-model="adminForm.balance" type="number"></div><div class="field"><label>状态</label><select v-model="adminForm.status"><option value="active">正常</option><option value="banned">封禁</option></select></div><div class="field"><label>角色</label><select v-model="adminForm.account_role"><option value="member">User</option><option value="agent">Agent</option><option value="admin">Admin</option><option value="owner">Owner</option></select></div><div class="field"><label class="switch"><input v-model="adminForm.strategy_user" type="checkbox"> User 策略</label></div><div class="field"><label class="switch"><input v-model="adminForm.strategy_agent" type="checkbox"> Agent 策略</label></div></div><button class="btn primary" style="margin-top:15px" @click="saveUser">保存用户</button></div></div>
          <div v-else-if="adminTab==='orders'" class="panel"><div class="page-head"><div><h3>速刷订单</h3><p>可同步上游状态、申请补单、上游退款或仅退款。</p></div><button class="btn primary" @click="syncOrders">更新速刷订单</button></div><div class="table-wrap"><table class="table"><thead><tr><th>订单号</th><th>用户</th><th>商品</th><th>用户花费</th><th>成本</th><th>利润</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{o.upstream_order_no||o.order_no}}</td><td>{{o.nickname||o.username}}</td><td>{{o.product_name}}</td><td>{{money(o.user_price)}}</td><td>{{money(o.cost_price)}}</td><td>{{money(o.profit)}}</td><td><span class="badge" :class="stateClass(o.state)">{{o.state}}</span></td><td><div style="display:flex;gap:6px"><button v-if="o.can_retry" class="btn sm warning" @click="adminRetry(o)">补单</button><button v-if="o.can_refund" class="btn sm danger" @click="adminRefund(o,false)">上游退款</button><button class="btn sm danger" @click="adminRefund(o,true)">仅退款</button></div></td></tr></tbody></table></div></div>
          <div v-else-if="adminTab==='cards'" class="two-col"><div class="panel"><h3>批量生成卡密</h3><div class="form-grid"><div class="field"><label>数量</label><input v-model="adminForm.count" type="number" min="1" value="1"></div><div class="field"><label>每张额度</label><input v-model="adminForm.amount" type="number" min="1"></div><div class="field"><label>最多使用次数</label><input v-model="adminForm.uses" type="number" min="-1" value="1"><span class="hint">-1 为无限次，0 为不能再兑换；每次兑换都会记录用户。</span></div><div class="field"><label>前缀</label><input v-model="adminForm.prefix"></div><div class="field full"><label>备注</label><input v-model="adminForm.note"></div></div><button class="btn primary" style="margin-top:15px" @click="generateCards">生成卡密</button></div><div class="panel"><div class="page-head"><div><h3>卡密列表</h3><p class="hint">可修改额度、剩余次数和备注；销毁会保留历史记录。</p></div><button class="btn ghost" @click="loadAdmin('cards')">刷新</button></div><div class="table-wrap"><table class="table"><thead><tr><th>卡密</th><th>额度</th><th>总次数</th><th>剩余次数</th><th>状态</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="c in cards" :key="c.id"><td><input v-model.trim="c.code" style="min-width:150px"><div class="hint">{{c.created_at}}</div></td><td><input v-model.number="c.amount" type="number" min="1" style="width:100px"></td><td><input v-model.number="c.total_uses" type="number" min="-1" style="width:90px"></td><td><input v-model.number="c.remaining_uses" type="number" min="-1" style="width:90px"></td><td><span class="badge" :class="c.enabled?'success':'danger'">{{c.enabled?'可用':'已销毁'}}</span></td><td><input v-model="c.note" style="min-width:120px"></td><td><div style="display:flex;gap:6px"><button class="btn sm primary" @click="saveCard(c)">保存</button><button class="btn sm danger" @click="destroyCard(c)">销毁</button></div></td></tr><tr v-if="!cards.length"><td colspan="7" class="empty">暂无卡密</td></tr></tbody></table></div></div></div>
          <div v-else-if="adminTab==='payments'" class="two-col"><div class="panel"><div class="page-head"><div><h3>易支付商户</h3><p class="hint">商户密钥不会回显；编辑时密钥留空表示保留原密钥。</p></div><button class="btn sm" @click="newMerchant">新增</button></div><div class="table-wrap"><table class="table"><tr v-for="m in payments.merchants||[]" :key="m.id"><td>{{m.name}}<div class="hint">{{m.pid}}</div></td><td>{{m.endpoint}}</td><td>{{m.enabled?'启用':'停用'}}</td><td><button class="btn sm" @click="editMerchant(m)">编辑</button></td></tr></table></div><div class="form-grid" style="margin-top:15px"><div class="field"><label>名称</label><input v-model="adminForm.name"></div><div class="field"><label>网关地址</label><input v-model="adminForm.endpoint" placeholder="https://pay.example.com"></div><div class="field"><label>商户ID</label><input v-model="adminForm.pid"></div><div class="field"><label>商户密钥</label><input v-model="adminForm.merchant_key" type="password" placeholder="新增必填，编辑留空保留"></div><div class="field"><label class="switch"><input v-model="adminForm.enabled" type="checkbox"> 启用</label></div></div><button class="btn primary" style="margin-top:13px" @click="saveMerchant">保存商户</button></div><div class="panel"><div class="page-head"><div><h3>支付通道</h3><p class="hint">例如微信绑定 1 号商户，支付宝绑定 2 号商户。</p></div><button class="btn sm" @click="newChannel">新增</button></div><div class="table-wrap"><table class="table"><tr v-for="c in payments.channels||[]" :key="c.id"><td>{{c.name}}<div class="hint">{{c.code}}</div></td><td>{{c.pay_type}}</td><td>{{c.merchant_name}}</td><td>{{c.enabled?'启用':'停用'}}</td><td><button class="btn sm" @click="editChannel(c)">编辑</button></td></tr></table></div><div class="form-grid" style="margin-top:15px"><div class="field"><label>通道编码</label><input v-model="adminForm.code"></div><div class="field"><label>通道名称</label><input v-model="adminForm.name"></div><div class="field"><label>支付方式</label><input v-model="adminForm.pay_type" placeholder="wxpay / alipay"></div><div class="field"><label>易支付商户</label><select v-model.number="adminForm.merchant_id"><option value="0">请选择</option><option v-for="m in payments.merchants||[]" :value="m.id">{{m.name}} · {{m.pid}}</option></select></div><div class="field"><label>排序</label><input v-model.number="adminForm.sort_order" type="number"></div><div class="field"><label class="switch"><input v-model="adminForm.enabled" type="checkbox"> 启用</label></div></div><button class="btn primary" style="margin-top:13px" @click="saveChannel">保存通道</button></div></div>
          <div v-else-if="adminTab==='upstream'" class="two-col"><div class="panel"><h3>上游账户</h3><div class="table-wrap"><table class="table"><tr v-for="u in upstreams" :key="u.id"><td>{{u.name}}</td><td>{{u.base_url}}</td><td>{{u.enabled?'启用':'停用'}}</td><td><button class="btn sm" @click="adminForm={...u}">编辑</button></td></tr></table></div></div><div class="panel"><h3>新增 / 编辑上游</h3><div class="form-grid"><div class="field"><label>名称</label><input v-model="adminForm.name"></div><div class="field"><label>Base URL</label><input v-model="adminForm.base_url"></div><div class="field"><label>上游 UID</label><input v-model="adminForm.upstream_uid" type="number"></div><div class="field"><label>上游 API Key</label><input v-model="adminForm.upstream_api_key" type="password"></div><div class="field"><label class="switch"><input v-model="adminForm.enabled" type="checkbox"> 启用</label></div><div class="field"><label class="switch"><input v-model="adminForm.is_default" type="checkbox"> 默认账户</label></div></div><button class="btn primary" style="margin-top:15px" @click="saveUpstream">保存</button></div></div>
          <div v-else-if="adminTab==='settings'" class="panel"><div class="page-head"><div><h3>系统设置</h3><p>所有敏感配置仅保存到服务端；后台管理员登录始终强制图片验证码。</p></div><button class="btn ghost" @click="loadAdmin('settings')">刷新</button></div><h4>SEO 与站点</h4><div class="form-grid"><div class="field"><label>网站名称</label><input v-model="settings.site_name"></div><div class="field"><label>额度名称</label><input v-model="settings.currency_name"></div><div class="field"><label>关键词</label><input v-model="settings.site_keywords"></div><div class="field"><label>网站图标</label><input v-model="settings.site_favicon" placeholder="/favicon.ico 或完整 URL"></div><div class="field"><label>Logo</label><input v-model="settings.site_logo"></div><div class="field full"><label>网站描述</label><textarea v-model="settings.site_description"></textarea></div><div class="field full"><label>页脚</label><input v-model="settings.seo_footer"></div><div class="field"><label>后台路径</label><input v-model="settings.admin_path"></div><div class="field"><label>说说图片来源</label><select v-model="settings.feed_image_mode"><option value="self_proxy">自己服务器代理（推荐）</option><option value="upstream_proxy">上游代理链接</option></select></div></div><h4 style="margin-top:22px">下单与登录注册</h4><div class="form-grid"><div class="field"><label>前台下单</label><select v-model="settings.frontend_order_enabled"><option value="0">关闭</option><option value="1">开启</option></select></div><div class="field"><label>对接下单</label><select v-model="settings.api_order_enabled"><option value="0">关闭</option><option value="1">开启</option></select></div><div class="field"><label>登录图片验证码</label><select v-model="settings.login_need_image_captcha"><option value="0">关闭（后台仍强制）</option><option value="1">开启</option></select></div><div class="field"><label>登录短信验证码</label><select v-model="settings.login_need_sms"><option value="0">否</option><option value="1">是</option></select></div><div class="field"><label>登录邮箱验证码</label><select v-model="settings.login_need_email"><option value="0">否</option><option value="1">是</option></select></div><div class="field"><label>登录极验</label><select v-model="settings.login_need_geetest"><option value="0">否</option><option value="1">是</option></select></div><div class="field"><label>注册需要邮箱</label><select v-model="settings.register_need_email"><option value="0">否</option><option value="1">是</option></select></div><div class="field"><label>注册需要手机号</label><select v-model="settings.register_need_mobile"><option value="0">否</option><option value="1">是</option></select></div><div class="field"><label>注册图片验证码</label><select v-model="settings.register_need_image_captcha"><option value="0">否</option><option value="1">是</option></select></div><div class="field"><label>注册短信验证码</label><select v-model="settings.register_need_sms_code"><option value="0">否</option><option value="1">是</option></select></div><div class="field"><label>注册邮箱验证码</label><select v-model="settings.register_need_email_code"><option value="0">否</option><option value="1">是</option></select></div><div class="field"><label>默认 User 策略</label><select v-model="settings.default_register_strategy_user"><option value="0">否</option><option value="1">是</option></select></div><div class="field"><label>默认 Agent 策略</label><select v-model="settings.default_register_strategy_agent"><option value="0">否</option><option value="1">是</option></select></div></div><h4 style="margin-top:22px">SMTP 发件</h4><div class="form-grid"><div class="field"><label>服务器</label><input v-model="settings.smtp_config.host"></div><div class="field"><label>端口</label><input v-model.number="settings.smtp_config.port" type="number"></div><div class="field"><label>用户名</label><input v-model="settings.smtp_config.username"></div><div class="field"><label>密码</label><input v-model="settings.smtp_config.password" type="password"></div><div class="field"><label>加密</label><select v-model="settings.smtp_config.encryption"><option value="ssl">SSL</option><option value="tls">TLS</option><option value="none">无</option></select></div><div class="field"><label>发件邮箱</label><input v-model="settings.smtp_config.from" type="email"></div><div class="field"><label>发件人名称</label><input v-model="settings.smtp_config.from_name"></div></div><h4 style="margin-top:22px">短信与极验</h4><div class="form-grid"><div class="field"><label>短信服务商</label><select v-model="settings.sms_provider"><option value="tencent">腾讯云</option><option value="aliyun">阿里云</option><option value="custom_http">自定义 HTTP</option></select></div><div class="field"><label>短信配置 JSON</label><textarea v-model="settings.sms_config_text" placeholder="填写所选短信商需要的 JSON 配置"></textarea></div><div class="field"><label>极验配置 JSON</label><textarea v-model="settings.geetest_config_text" placeholder="captcha_id、private_key、endpoint 等"></textarea></div></div><h4 style="margin-top:22px">邀请与对接条件</h4><div class="form-grid"><div class="field"><label>有效邀请模式</label><select v-model="settings.invite_valid_mode"><option value="total_consume">累计消费</option><option value="total_recharge">累计充值</option><option value="balance">余额</option></select></div><div class="field"><label>有效邀请门槛</label><input v-model.number="settings.invite_valid_value" type="number"></div><div class="field"><label>API 条件模式</label><select v-model="settings.api_condition_mode"><option value="total_consume">累计消费</option><option value="total_recharge">累计充值</option><option value="balance">余额</option><option value="invite_count">邀请用户数</option></select></div><div class="field"><label>API 条件比较符</label><select v-model="settings.api_condition_operator"><option value="=">等于</option><option value=">=">大于等于</option><option value="<=">小于等于</option></select></div><div class="field"><label>API 条件值</label><input v-model="settings.api_condition_value"></div><div class="field"><label>余额不足降级</label><select v-model="settings.balance_downgrade_enabled"><option value="0">否</option><option value="1">是</option></select></div><div class="field"><label>邀请码价格模式</label><select v-model="settings.invite_code_price_rules.mode"><option value="fixed">固定价格</option><option value="length">按长度</option></select></div><div class="field" v-if="settings.invite_code_price_rules.mode==='fixed'"><label>固定价格</label><input v-model.number="settings.invite_code_price_rules.fixed" type="number" min="0"></div><div class="field full" v-else><label>按长度价格 JSON（6-48）</label><textarea v-model="settings.invite_code_price_rules_text" placeholder="例如 {\"6\":100,\"20\":500}"></textarea></div></div><button class="btn primary" style="margin-top:16px" @click="saveSettings">保存设置</button></div>
          <div v-else-if="adminTab==='logs'" class="panel"><div class="page-head"><h3>系统日志</h3><button class="btn ghost" @click="loadAdmin('logs')">刷新</button></div><div class="table-wrap"><table class="table"><tr v-for="l in logs" :key="l.id"><td>{{l.created_at}}</td><td><span class="badge" :class="l.level==='error'?'danger':'info'">{{l.level}}</span></td><td>{{l.channel}}</td><td>{{l.message}}</td><td><code>{{l.context_json}}</code></td></tr></table></div></div>
        </div></div></section>
      </main>
    </div>
  </div>
  __SEO_FOOTER_BLOCK__
  <div v-if="detailOrder" class="modal-backdrop" @click.self="detailOrder=null"><div class="modal"><div class="modal-head"><h3>订单详情</h3><button class="close" @click="detailOrder=null">×</button></div><div class="grid"><div class="stat"><small>订单号</small><strong style="font-size:16px;word-break:break-all">{{detailOrder.upstream_order_no||detailOrder.order_no}}</strong></div><div class="stat"><small>状态</small><strong style="font-size:18px">{{detailOrder.state}}</strong></div><div class="stat"><small>用户花费</small><strong style="font-size:18px">{{money(detailOrder.user_price)}} {{currency}}</strong></div><div class="stat"><small>成本 / 利润</small><strong style="font-size:18px">{{money(detailOrder.cost_price)}} / {{money(detailOrder.profit)}}</strong></div></div><div class="panel" style="margin-top:16px;background:#fbfcff"><h3>执行信息</h3><p>QQ：{{detailOrder.target_qq}} · 数量：{{detailOrder.quantity}} · 说说ID：{{detailOrder.feed_id||'未指定'}}</p><p>{{detailOrder.message||'暂无上游消息'}}</p><div v-if="detailOrder.extra_input" class="json-box">{{pretty(detailOrder.extra_input)}}</div></div></div></div>
  <div v-if="notice" class="notice">{{notice}}</div>
</div>

<script>
const BOOT=__BOOT__;
const {createApp}=Vue;
createApp({
 data(){return{
  boot:BOOT,user:BOOT.user,authMode:'login',loginMode:'user',notice:'',loading:false,mobileNav:false,tab:'home',adminTab:'dashboard',
  products:[],orders:[],groups:[],payments:{channels:[],merchants:[]},rechargeOrders:[],inviteCodes:[],feed:[],feedQq:'',selectedProduct:null,detailOrder:null,gateway:null,quotedPrice:null,rechargeAmount:'',rechargeChannel:'',inviteLength:20,inviteCustom:'',
  form:{qq:'',num:'',feed_id:'',is_delayed:0,limit:'',extra:{}},cardCode:'',
  login:{username:'',password:'',captcha:'',admin:false},register:{username:'',nickname:'',qq:'',password:'',email:'',mobile:'',invite_code:'',captcha:''},
  dashboard:{},users:[],cards:[],settings:{site_name:'',site_keywords:'',site_description:'',site_favicon:'',site_logo:'',seo_footer:'',currency_name:'额度',admin_path:'/admin',feed_image_mode:'self_proxy',frontend_order_enabled:'1',api_order_enabled:'1',login_need_image_captcha:'0',login_need_sms:'0',login_need_email:'0',login_need_geetest:'0',register_need_email:'0',register_need_mobile:'0',register_need_image_captcha:'1',register_need_sms_code:'0',register_need_email_code:'0',default_register_strategy_user:'1',default_register_strategy_agent:'0',balance_downgrade_enabled:'0',api_condition_mode:'total_consume',api_condition_operator:'>=',api_condition_value:'0',invite_valid_mode:'total_consume',invite_valid_value:'100000',sms_provider:'custom_http',smtp_config:{host:'',port:465,username:'',password:'',encryption:'ssl',from:'',from_name:''},sms_config:{},geetest_config:{},invite_code_price_rules:{mode:'fixed',fixed:0},sms_config_text:'{}',geetest_config_text:'{}',invite_code_price_rules_text:'{}'},upstreams:[],logs:[],adminForm:{}
 }},
 computed:{
  isLogged(){return !!this.user},isAdmin(){return this.user&&['owner','admin'].includes(this.user.account_role)},isAgent(){return this.user&&Number(this.user.strategy_agent)===1},adminBase(){return String(this.boot.adminPath||'/admin').replace(/\/$/,'')},
  selectedInputs(){return this.selectedProduct&&Array.isArray(this.selectedProduct.input)&&this.selectedProduct.input.length?this.selectedProduct.input:[{name:'qq',type:'qq',title:'下单QQ号',placeholder:'请输入QQ号',required:true},{name:'num',type:'setNum',title:'下单数量',placeholder:'请输入数量',required:true}]},
  selectedFeedInput(){return this.selectedInputs.find(x=>String(x.type).toLowerCase()==='feed')},
  qqAvatar(){return this.form.qq&&/^[1-9][0-9]{4,14}$/.test(String(this.form.qq))?'https://q1.qlogo.cn/g?b=qq&nk='+encodeURIComponent(this.form.qq)+'&s=100':'https://q1.qlogo.cn/g?b=qq&nk=10000&s=100'},
  currency(){return this.boot.currency||'额度'}
 },
 mounted(){if(this.user)this.loadHome()},
 methods:{
  endpoint(path){if(path.startsWith('/admin/api/'))return this.adminBase+'/api/'+path.slice(10);return path},
  async api(path,options={}){this.loading=true;try{const opts={credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options};const res=await fetch(this.endpoint(path),opts);const j=await res.json().catch(()=>({success:false,message:'服务器返回异常'}));if(!res.ok||j.success===false)throw new Error(j.message||j.msg||'请求失败');return j}finally{this.loading=false}},
  toast(text){this.notice=String(text);clearTimeout(this._toastTimer);this._toastTimer=setTimeout(()=>{this.notice=''},3800)},
  async doLogin(){try{this.login.admin=this.loginMode==='admin';const j=await this.api('/auth/login',{method:'POST',body:JSON.stringify(this.login)});this.user=j.data;this.toast('登录成功');this.loadHome()}catch(e){this.toast(e.message)}},
  async doRegister(){try{const j=await this.api('/auth/register',{method:'POST',body:JSON.stringify(this.register)});this.user=j.data;this.toast('注册成功');this.loadHome()}catch(e){this.toast(e.message)}},
  refreshCaptcha(e){e.target.src='/captcha/image?'+Date.now()},
  logout(){fetch('/auth/logout',{credentials:'same-origin'}).finally(()=>location.reload())},
  loadHome(){this.loadProducts();this.loadOrders();if(this.isAdmin)this.loadAdmin('dashboard');if(this.tab==='recharge')this.loadPayments();},
  async loadProducts(){try{const j=await this.api('/user/api/products');this.products=j.data||[]}catch(e){}},
  async loadOrders(){try{const j=await this.api('/user/api/orders');this.orders=j.data||[]}catch(e){}},
  async loadPayments(){try{const j=await this.api('/user/api/payments');this.payments=j.data||{channels:[]};const r=await this.api('/user/api/recharge/orders');this.rechargeOrders=r.data||[]}catch(e){}},
  async loadInvites(){try{const j=await this.api('/user/api/invites');this.inviteCodes=j.data||[]}catch(e){}},
  selectTab(t){this.tab=t;this.mobileNav=false;if(['place','dock','products'].includes(t))this.loadProducts();if(t==='orders')this.loadOrders();if(t==='groups')this.loadGroups();if(t==='recharge')this.loadPayments();if(t==='invites')this.loadInvites()},
  async loadGroups(){try{const j=await this.api('/user/api/groups');this.groups=j.data||[]}catch(e){}},
  selectAdmin(t){this.adminTab=t;this.loadAdmin(t)},
  async loadAdmin(t){const map={dashboard:'/admin/api/dashboard',products:'/admin/api/products',groups:'/admin/api/groups',users:'/admin/api/users',orders:'/admin/api/orders',cards:'/admin/api/cards',payments:'/admin/api/payments',settings:'/admin/api/settings',upstream:'/admin/api/upstream',logs:'/admin/api/logs'};if(!map[t])return;try{const j=await this.api(map[t]);if(t==='dashboard')this.dashboard=j.data||{};if(t==='products')this.products=j.data||[];if(t==='groups')this.groups=j.data||[];if(t==='users')this.users=j.data||[];if(t==='orders')this.orders=j.data||[];if(t==='cards')this.cards=j.data||[];if(t==='payments')this.payments={channels:[],merchants:[],...(j.data||{})};if(t==='settings')this.settings=this.normalizeSettings(j.data||{});if(t==='upstream')this.upstreams=j.data||[];if(t==='logs')this.logs=j.data||[]}catch(e){this.toast(e.message)}},
  openAdmin(t){this.tab='admin';this.selectAdmin(t)},
  chooseProduct(p,mode='place'){this.selectedProduct=p;this.form={qq:this.user.qq||'',num:p.min_num||p.step_num||1,feed_id:'',is_delayed:0,limit:'',extra:{}};this.quotedPrice=null;this.tab=mode;this.quotePrice()},
  fieldType(f){return String(f.type||'text').toLowerCase()},
  fieldValue(f){const type=this.fieldType(f);if(type==='qq')return this.form.qq;if(['setnum','num','number'].includes(type))return this.form.num;if(type==='feed')return this.form.feed_id;return this.form.extra[f.name]||''},
  setField(f,value){const type=this.fieldType(f);if(type==='qq')this.form.qq=value;else if(['setnum','num','number'].includes(type))this.form.num=value;else if(type==='feed')this.form.feed_id=value;else this.form.extra[f.name]=value;if(type==='qq'||['setnum','num','number'].includes(type))this.quotePrice()},
  async quotePrice(){if(!this.selectedProduct||!this.form.num)return;const n=Number(this.form.num);if(!Number.isFinite(n)||n<=0)return;try{const j=await this.api('/user/api/order/price',{method:'POST',body:JSON.stringify({sign:this.selectedProduct.upstream_sign,num:n,is_delayed:this.form.is_delayed?1:0})});this.quotedPrice=j.data||null}catch(e){this.quotedPrice=null}},
  async submitOrder(){if(!this.selectedProduct)return this.toast('请先选择商品');const payload={sign:this.selectedProduct.upstream_sign,qq:this.form.qq,num:Number(this.form.num),feed_id:this.form.feed_id||'',is_delayed:this.form.is_delayed?1:0,limit:this.form.limit===''?undefined:Number(this.form.limit),...this.form.extra};try{const j=await this.api('/user/api/order/create',{method:'POST',body:JSON.stringify(payload)});this.toast('下单成功，订单号：'+(j.data.order_no||j.data.upstream_order_no||''));this.orders.unshift(j.data);this.tab='orders';this.selectedProduct=null;await this.loadOrders()}catch(e){this.toast(e.message)}},
  async submitApiOrder(){if(!this.isAgent||!this.user.api_key)return this.toast('当前账号未生成 API Key');return this.submitOrder()},
  async refreshFeed(){if(!this.feedQq)return this.toast('请输入查询QQ号');try{const j=await this.api('/user/api/feed?qq='+encodeURIComponent(this.feedQq));this.feed=Array.isArray(j.data)?j.data:[];this.toast('说说列表已更新')}catch(e){this.toast(e.message)}},
  selectFeed(item){this.form.feed_id=item.feed_id||item.id||'';this.toast('已选择说说 '+this.form.feed_id)},
  feedImage(img){return img.display||img.proxy||img.original||''},
  async showOrder(o){try{const j=await this.api('/user/api/order/detail?bid='+encodeURIComponent(o.upstream_order_no||o.order_no));this.detailOrder=j.data}catch(e){this.toast(e.message)}},
  async retry(o){if(!confirm('补单只能申请一次，确定继续吗？'))return;try{const j=await this.api('/user/api/order/retry',{method:'POST',body:JSON.stringify({bid:o.upstream_order_no||o.order_no})});this.toast(j.message||'补单申请成功');await this.loadOrders()}catch(e){this.toast(e.message)}},
  async refund(o){if(!confirm('确定申请退款吗？'))return;try{const j=await this.api('/user/api/order/refund',{method:'POST',body:JSON.stringify({bid:o.upstream_order_no||o.order_no})});this.toast(j.message||'退款成功');await this.loadOrders()}catch(e){this.toast(e.message)}},
  async createRecharge(){const amount=Number(this.rechargeAmount||0),channel=Number(this.rechargeChannel||0);if(amount<=0||channel<=0)return this.toast('请填写充值额度并选择支付通道');try{const j=await this.api('/user/api/recharge/create',{method:'POST',body:JSON.stringify({channel_id:channel,credit_amount:amount})});this.gateway=j.data;this.toast('支付订单已创建，请完成支付');await this.loadPayments()}catch(e){this.toast(e.message)}},
  async redeemCard(){if(!this.cardCode)return this.toast('请输入卡密');try{const j=await this.api('/card/redeem',{method:'POST',body:JSON.stringify({code:this.cardCode})});this.toast(j.message||'卡密充值成功');this.cardCode='';location.reload()}catch(e){this.toast(e.message)}},
  async createInvite(){try{const j=await this.api('/user/api/invite/create',{method:'POST',body:JSON.stringify({length:Number(this.inviteLength||20),code:this.inviteCustom||''})});this.toast('邀请码创建成功');this.inviteCustom='';await this.loadInvites()}catch(e){this.toast(e.message)}},
  async save(path,data,after){try{const j=await this.api(path,{method:'POST',body:JSON.stringify(data)});this.toast(j.message||'保存成功');if(after)await after(j.data);return j}catch(e){this.toast(e.message)}},
  async syncProducts(){await this.save('/admin/api/products/sync',{},()=>this.loadAdmin('products'))},
  async saveProduct(p){await this.save('/admin/api/products/save',{id:p.id,allow_frontend:p.allow_frontend,allow_api:p.allow_api,enabled:p.enabled,discounts:p.discounts||[]},()=>this.loadAdmin('products'))},
  parseJson(value,fallback={}){if(value&&typeof value==='object')return value;try{const parsed=JSON.parse(String(value||''));return parsed&&typeof parsed==='object'?parsed:{...fallback}}catch(e){return {...fallback}}},
  normalizeSettings(raw){const x={...this.settings,...raw};x.smtp_config=this.parseJson(raw.smtp_config,{host:'',port:465,username:'',password:'',encryption:'ssl',from:'',from_name:''});x.sms_config=this.parseJson(raw.sms_config,{});x.geetest_config=this.parseJson(raw.geetest_config,{});x.invite_code_price_rules=this.parseJson(raw.invite_code_price_rules,{mode:'fixed',fixed:0});x.sms_config_text=JSON.stringify(x.sms_config,null,2);x.geetest_config_text=JSON.stringify(x.geetest_config,null,2);x.invite_code_price_rules_text=JSON.stringify(x.invite_code_price_rules,null,2);return x},
  settingsPayload(){const x={...this.settings};try{x.sms_config=JSON.parse(this.settings.sms_config_text||'{}')}catch(e){throw new Error('短信配置 JSON 格式不正确')}try{x.geetest_config=JSON.parse(this.settings.geetest_config_text||'{}')}catch(e){throw new Error('极验配置 JSON 格式不正确')}if(this.settings.invite_code_price_rules.mode==='length'){try{x.invite_code_price_rules={mode:'length',...JSON.parse(this.settings.invite_code_price_rules_text||'{}')}}catch(e){throw new Error('邀请码长度价格 JSON 格式不正确')}}else{x.invite_code_price_rules={mode:'fixed',fixed:Number(this.settings.invite_code_price_rules.fixed||0)}}return x},
  editGroup(g){this.adminForm={...g}},
  async saveGroup(){await this.save('/admin/api/groups/save',this.adminForm,()=>this.loadAdmin('groups'))},
  async saveSettings(){try{await this.save('/admin/api/settings/save',this.settingsPayload(),()=>this.loadAdmin('settings'))}catch(e){this.toast(e.message)}},
  editUser(u){this.adminForm={...u,password:''}},
  async saveUser(){await this.save('/admin/api/users/save',this.adminForm,()=>this.loadAdmin('users'))},
  async resetKey(u){await this.save('/admin/api/users/reset-key',{id:u.id},async()=>{this.toast('API Key已重置');await this.loadAdmin('users')})},
  async deleteUser(u){if(!confirm('确定删除该用户吗？系统会保留数据并模拟删除。'))return;await this.save('/admin/api/users/delete',{id:u.id},()=>this.loadAdmin('users'))},
  async syncOrders(){await this.save('/admin/api/orders/sync',{},()=>this.loadAdmin('orders'))},
  async adminRetry(o){await this.save('/admin/api/orders/retry',{id:o.id},()=>this.loadAdmin('orders'))},
  async adminRefund(o,manual=false){await this.save(manual?'/admin/api/orders/manual-refund':'/admin/api/orders/refund',{id:o.id},()=>this.loadAdmin('orders'))},
  async generateCards(){await this.save('/admin/api/cards/generate',this.adminForm,()=>this.loadAdmin('cards'))},
  async saveCard(c){await this.save('/admin/api/cards/save',{id:c.id,code:c.code,amount:Number(c.amount),total_uses:Number(c.total_uses),remaining_uses:Number(c.remaining_uses),enabled:c.enabled,note:c.note},()=>this.loadAdmin('cards'))},
  async destroyCard(c){if(confirm('确定销毁此卡密吗？销毁后仍保留卡密使用记录。'))await this.save('/admin/api/cards/destroy',{id:c.id},()=>this.loadAdmin('cards'))},
  newMerchant(){this.adminForm={id:0,name:'',endpoint:'',pid:'',merchant_key:'',enabled:1}},
  editMerchant(m){this.adminForm={...m,merchant_key:''}},
  async saveMerchant(){await this.save('/admin/api/payments/merchant',this.adminForm,()=>{this.newMerchant();return this.loadAdmin('payments')})},
  newChannel(){this.adminForm={id:0,code:'',name:'',pay_type:'',merchant_id:this.payments.merchants?.[0]?.id||0,enabled:1,sort_order:0}},
  editChannel(c){this.adminForm={...c}},
  async saveChannel(){await this.save('/admin/api/payments/channel',this.adminForm,()=>{this.newChannel();return this.loadAdmin('payments')})},
  async saveUpstream(){await this.save('/admin/api/upstream/save',this.adminForm,()=>this.loadAdmin('upstream'))},
  money(n){return Number(n||0).toLocaleString()},stateClass(s){return ['完成','已完成'].includes(s)?'success':s==='失败'?'danger':'warning'},descText(d){return Array.isArray(d)?d.join(' · '):String(d||'')},pretty(v){return JSON.stringify(v||{},null,2)},imageCaptchaNeeded(){return this.loginMode==='admin'||this.settings.login_need_image_captcha==='1'||this.settings.login_need_image_captcha===1}
 }
}).mount('#app');
</script>
</body>
</html>

